/*
 * A267598  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 177" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A267598
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   a(n) = ((n + floor_sqrt(n + 2)) % 2)
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  = (1 - (-1)^(n + ⌊√(n+2)⌋))/2, i.e. the parity of n + ⌊√(n+2)⌋. */

#include <stdint.h>

/* Integer floor square‑root for 64‑bit values. */
static uint64_t floor_sqrt_u64(uint64_t n)
{
    if (n < 2) return n;
    uint64_t low  = 1;
    uint64_t high = 0xFFFFFFFFULL;          /* sqrt(2^64-1) */
    while (low <= high) {
        uint64_t mid = low + ((high - low) >> 1);
        uint64_t div = n / mid;              /* mid > 0 */
        if (mid > div) {
            high = mid - 1;
        } else {
            if ((mid + 1) > div) return mid;
            low  = mid + 1;
        }
    }
    return high;
}

seq_t a(idx_t n)
{
    uint64_t s = floor_sqrt_u64((uint64_t)n + 2ULL);
    return (seq_t)(((n ^ s) & 1ULL));
}
